sys.path.insert(0, "output/tests")
import float64_diagnostic as fd

def _j(o):
    if isinstance(o, np.integer): return int(o)
    if isinstance(o, np.floating): return float(o)
    if isinstance(o, np.ndarray): return o.tolist()
    raise TypeError(f"{type(o)}: {o}")

orig_dumps = json.dumps
def spy(obj, **kw):
    kw.pop("default", None)
    class C(json.JSONEncoder):
        def default(self, o):
            try:
                return _j(o)
            except TypeError:
                import traceback; traceback.print_stack(); raise
    return orig_dumps(obj, cls=C, **kw)
json.dumps = spy
try:
    fd.run()
except Exception as e:
    print("RUN ERR", type(e).__name__, str(e)[:120])
finally:
    json.dumps = orig_dumps
EOF

