import sys, json, numpy as np
sys.path.insert(0, "output/tests")
import float64_diagnostic as fd

# walk the report tree to find int64 leaves and their paths
def walk(o, path):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from walk(v, path + [k])
    elif isinstance(o, list):
        if o and all(isinstance(x, (int, float)) for x in o):
            return
        for i, v in enumerate(o[:3]):
            yield from walk(v, path + [i])
    elif isinstance(o, np.integer):
        yield path

orig_dumps = json.dumps
report_box = {}
class Hook(json.JSONEncoder):
    def __init__(self, *a, **kw):
        super().__init__(*a, **kw)
    def default(self, o):
        return int(o) if isinstance(o, np.integer) else None
# rebuild report by calling internals manually is complex; instead patch write to capture
src = open("output/tests/float64_diagnostic.py").read()
g = {"__file__": "output/tests/float64_diagnostic.py", "__name__": "fd"}
exec(src.replace('OUT.write_text(json.dumps(report, indent=1, default=_jsonable))',
                 'report_box["r"] = report'), g)
g['run']()
rep = report_box["r"]
bad = list(walk(rep, []))
print("int64 leaf paths:", len(bad))
from collections import Counter
print(Counter(tuple(p[:4]) for p in bad).most_common(8))
EOF

